SET NOCOUNT ON;
SET XACT_ABORT ON;
USE [ibcmd_rs_05_online_a1];
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN TRY
BEGIN TRANSACTION;
DECLARE @LockResult int;
EXEC @LockResult = sys.sp_getapplock @Resource=N'ibcmd-rs:main-activation', @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=0;
IF @LockResult < 0 THROW 57200, 'main activation application lock is busy', 1;
DECLARE @ExpectedStage TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedStage VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4',0, 165,0x68173761147FEB4F08F70888C846710869E4B683FD5696550561E82ECAAA77FA);
