DECLARE @ExpectedActive TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedActive VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4',0, 165,0x420D2F658A2CBD564081D9D40AAE6B3C3305AE28B725FB0364F25F6841BE8AC3);
INSERT @ExpectedActive VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4.0',0, 680,0xACC5DA75D0C8F68301DEC863D44C1FA952D020CD0CC8937CC106ADE64713DC8C);
INSERT @ExpectedActive VALUES (N'root',0, 45,0xADFE2E91D2EFB05910281F6EFBB026ADFA876AA812D082C7F9E755028632A256);
INSERT @ExpectedActive VALUES (N'version',0, 28,0xEC6D68D22CDFA563A8FA7B32B6C827ABC9B84B1C0FEBC543EFC70E450459B795);
INSERT @ExpectedActive VALUES (N'versions',0, 340602,0x1E15F7BFA97DC63B17CCFDC353DCDFF15F907CFAB3D0A2E770CF30B633F683FA);
IF EXISTS (SELECT FileName,PartNo,CONVERT(bigint,DataSize),HASHBYTES('SHA2_256',BinaryData) FROM dbo.ConfigSave WITH (UPDLOCK,HOLDLOCK) EXCEPT SELECT FileName,PartNo,DataSize,Digest FROM @ExpectedStage) OR EXISTS (SELECT FileName,PartNo,DataSize,Digest FROM @ExpectedStage EXCEPT SELECT FileName,PartNo,CONVERT(bigint,DataSize),HASHBYTES('SHA2_256',BinaryData) FROM dbo.ConfigSave WITH (UPDLOCK,HOLDLOCK)) THROW 57201, 'ConfigSave exact snapshot drifted', 1;
IF EXISTS (SELECT E.FileName,E.PartNo FROM @ExpectedActive E LEFT JOIN dbo.Config T WITH (UPDLOCK,HOLDLOCK) ON T.FileName=E.FileName AND T.PartNo=E.PartNo AND CONVERT(bigint,T.DataSize)=E.DataSize AND HASHBYTES('SHA2_256',T.BinaryData)=E.Digest WHERE T.FileName IS NULL) THROW 57202, 'Config selected snapshot drifted', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated') THROW 57203, 'unexpected Config.DynamicallyUpdated row', 1;
IF EXISTS (SELECT 1 FROM dbo.Params WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'DynamicallyUpdated') THROW 57204, 'unexpected Params.DynamicallyUpdated row', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'313d9858-3995-4a4c-b2b0-15d2350417b4_dynupdate_4832dd20-0b9e-45e3-a3e7-095525bf9b3f' AND PartNo=0) THROW 57211, 'dynamic alias already exists', 1;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT N'313d9858-3995-4a4c-b2b0-15d2350417b4_dynupdate_4832dd20-0b9e-45e3-a3e7-095525bf9b3f',Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'313d9858-3995-4a4c-b2b0-15d2350417b4' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57212, 'online promotion source drifted', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'313d9858-3995-4a4c-b2b0-15d2350417b4_dynupdate_4832dd20-0b9e-45e3-a3e7-095525bf9b3f.0' AND PartNo=0) THROW 57211, 'dynamic alias already exists', 1;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT N'313d9858-3995-4a4c-b2b0-15d2350417b4_dynupdate_4832dd20-0b9e-45e3-a3e7-095525bf9b3f.0',Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'313d9858-3995-4a4c-b2b0-15d2350417b4.0' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57212, 'online promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'root' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT N'root',Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'root' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57212, 'online promotion source drifted', 1;
DELETE FROM dbo.Config WHERE FileName=N'version' AND PartNo=0;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT N'version',Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'version' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57212, 'online promotion source drifted', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WITH (UPDLOCK,HOLDLOCK) WHERE FileName=N'versions_dynupdate_4832dd20-0b9e-45e3-a3e7-095525bf9b3f' AND PartNo=0) THROW 57211, 'dynamic alias already exists', 1;
INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) SELECT N'versions_dynupdate_4832dd20-0b9e-45e3-a3e7-095525bf9b3f',Creation,Modified,Attributes,DataSize,BinaryData,PartNo FROM dbo.ConfigSave WHERE FileName=N'versions' AND PartNo=0;
IF @@ROWCOUNT <> 1 THROW 57212, 'online promotion source drifted', 1;
IF EXISTS (SELECT 1 FROM dbo.Config WHERE FileName=N'DynamicallyUpdated' AND PartNo=0) UPDATE dbo.Config SET Modified=SYSUTCDATETIME(),DataSize=45,BinaryData=0xEFBBBF7B312C312C34383332646432302D306239652D343565332D613365372D3039353532356266396233667D WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 ELSE INSERT dbo.Config (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) VALUES (N'DynamicallyUpdated',SYSUTCDATETIME(),SYSUTCDATETIME(),0,45,0xEFBBBF7B312C312C34383332646432302D306239652D343565332D613365372D3039353532356266396233667D,0);
IF @@ROWCOUNT <> 1 THROW 57213, 'Config.DynamicallyUpdated upsert failed', 1;
IF EXISTS (SELECT 1 FROM dbo.Params WHERE FileName=N'DynamicallyUpdated' AND PartNo=0) UPDATE dbo.Params SET Modified=SYSUTCDATETIME(),DataSize=82,BinaryData=0xEFBBBF7B302C322C38343861306135392D383830332D343435662D623839642D3363666165346639386262642C34383332646432302D306239652D343565332D613365372D3039353532356266396233667D WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 ELSE INSERT dbo.Params (FileName,Creation,Modified,Attributes,DataSize,BinaryData,PartNo) VALUES (N'DynamicallyUpdated',SYSUTCDATETIME(),SYSUTCDATETIME(),0,82,0xEFBBBF7B302C322C38343861306135392D383830332D343435662D623839642D3363666165346639386262642C34383332646432302D306239652D343565332D613365372D3039353532356266396233667D,0);
IF @@ROWCOUNT <> 1 THROW 57214, 'Params.DynamicallyUpdated upsert failed', 1;
DELETE FROM dbo.ConfigSave;
IF @@ROWCOUNT <> 5 THROW 57220, 'ConfigSave cleanup drifted', 1;
DECLARE @ExpectedPublished TABLE (FileName nvarchar(4000) NOT NULL, PartNo int NOT NULL, DataSize bigint NOT NULL, Digest varbinary(32) NOT NULL, PRIMARY KEY(FileName,PartNo));
INSERT @ExpectedPublished VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4_dynupdate_4832dd20-0b9e-45e3-a3e7-095525bf9b3f',0, 165,0x68173761147FEB4F08F70888C846710869E4B683FD5696550561E82ECAAA77FA);
INSERT @ExpectedPublished VALUES (N'313d9858-3995-4a4c-b2b0-15d2350417b4_dynupdate_4832dd20-0b9e-45e3-a3e7-095525bf9b3f.0',0, 704,0xEDBA3DF255288882280416A5E952BEFD9FF9A8F5C8F683D825B0D02CFCB08E5C);
INSERT @ExpectedPublished VALUES (N'root',0, 45,0xADFE2E91D2EFB05910281F6EFBB026ADFA876AA812D082C7F9E755028632A256);
INSERT @ExpectedPublished VALUES (N'version',0, 28,0xEC6D68D22CDFA563A8FA7B32B6C827ABC9B84B1C0FEBC543EFC70E450459B795);
INSERT @ExpectedPublished VALUES (N'versions_dynupdate_4832dd20-0b9e-45e3-a3e7-095525bf9b3f',0, 344212,0x46CF96CAF89193D71FFBCCEDD59202337FB95D696B0ACEA5DC4AC3E2E3FCBBA5);
IF EXISTS (SELECT E.FileName,E.PartNo FROM @ExpectedPublished E LEFT JOIN dbo.Config T WITH (UPDLOCK,HOLDLOCK) ON T.FileName=E.FileName AND T.PartNo=E.PartNo AND CONVERT(bigint,T.DataSize)=E.DataSize AND HASHBYTES('SHA2_256',T.BinaryData)=E.Digest WHERE T.FileName IS NULL) THROW 57222, 'Config selected snapshot drifted', 1;
IF (SELECT COUNT_BIG(*) FROM dbo.Config WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 AND CONVERT(bigint,DataSize)=45 AND HASHBYTES('SHA2_256',BinaryData)=0xB2BF1FCDC585D7CACD0B5416CE70C9285C614347C6E8586DAABA4B40567972ED) <> 1 THROW 57223, 'Config.DynamicallyUpdated postcondition failed', 1;
IF (SELECT COUNT_BIG(*) FROM dbo.Params WHERE FileName=N'DynamicallyUpdated' AND PartNo=0 AND CONVERT(bigint,DataSize)=82 AND HASHBYTES('SHA2_256',BinaryData)=0xF05F5EFB4431350C4C029514138680E18C0D4F808745119DDDBFF5D067C9C6B4) <> 1 THROW 57224, 'Params.DynamicallyUpdated postcondition failed', 1;
IF EXISTS (SELECT 1 FROM dbo.ConfigSave) THROW 57221, 'ConfigSave postcondition failed', 1;
COMMIT TRANSACTION;
END TRY
BEGIN CATCH
IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
THROW;
